#pragma once
// Served only by the password-protected setup AP, before changing network mode.
// The token is substituted in RAM and submitted in the POST body, never a URL.
constexpr char kLocalWifiMenu[] = "<form action='/local' method='get'><button>Local Mode</button></form>";
constexpr char kLocalWifiPage[] = R"LHLOCAL(<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Lighthouse Bridge · Local Mode</title>%PORTAL_HEAD%</head><body><main class="wrap"><h1>Local Mode</h1><p id="help">The bridge creates its own Wi-Fi without a router. Stay connected even if your phone reports no internet. Your web password and station assignments stay unchanged.</p><p id="matter">Alexa is unavailable in this mode. Existing home Wi-Fi and Matter pairings are retained for returning home.</p><form method="post" action="/local"><input type="hidden" name="token" value="%TOKEN%"><button id="activate" type="submit">Activate Local Mode</button></form><p><a href="/" id="back">Back</a></p><p id="address">After restart, reconnect to the bridge Wi-Fi and open http://192.168.4.1/.</p></main><script>let preferred;try{preferred=localStorage.getItem('lighthouse-bridge.language');}catch(_){}if(preferred==='de'||preferred!=='en'&&navigator.language.startsWith('de')){document.documentElement.lang='de';document.getElementById('help').textContent='Die Bridge stellt ein eigenes WLAN ohne Router bereit. Bleibe verbunden, auch wenn dein Handy kein Internet meldet. Web-Passwort und Stationszuordnungen bleiben erhalten.';document.getElementById('matter').textContent='Alexa ist in diesem Modus nicht erreichbar. Heim-WLAN und Matter-Kopplungen bleiben für die Rückkehr gespeichert.';document.getElementById('activate').textContent='Local Mode aktivieren';document.getElementById('back').textContent='Zurück';document.getElementById('address').textContent='Nach dem Neustart wieder mit dem Bridge-WLAN verbinden und http://192.168.4.1/ öffnen.';}</script></body></html>)LHLOCAL";
constexpr char kLocalWifiSaved[] = R"LHSAVED(<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Lighthouse Bridge · Local Mode</title>%PORTAL_HEAD%</head><body><main class="wrap"><span class="portal-mark" aria-hidden="true">◈</span><h1 id="saved-title">Starting Local Mode…</h1><p id="saved-help">The bridge is restarting. Reconnect to its Wi-Fi, even if your phone reports no internet.</p><p id="saved-address">The dashboard will be at http://192.168.4.1/.</p><a class="portal-open" href="http://192.168.4.1/" id="saved-open">Open Webinterface →</a><p class="portal-note" id="saved-note">Your Wi-Fi key, web password and station assignments stay unchanged.</p></main><script>let preferred;try{preferred=localStorage.getItem('lighthouse-bridge.language');}catch(_){}if(preferred==='de'||preferred!=='en'&&navigator.language.startsWith('de')){document.documentElement.lang='de';document.getElementById('saved-title').textContent='Local Mode wird gestartet…';document.getElementById('saved-help').textContent='Die Bridge startet neu. Verbinde dich wieder mit ihrem WLAN, auch wenn dein Handy kein Internet meldet.';document.getElementById('saved-address').textContent='Das Webinterface ist unter http://192.168.4.1/ erreichbar.';document.getElementById('saved-open').textContent='Webinterface öffnen →';document.getElementById('saved-note').textContent='WLAN-Schlüssel, Web-Passwort und Stationszuordnungen bleiben unverändert.';}setTimeout(()=>location.replace('http://192.168.4.1/'),5000);</script></body></html>)LHSAVED";
